def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    blocks = []
    for ri in range(len(row_bounds) - 1):
        r0, r1 = row_bounds[ri] + 1, row_bounds[ri + 1]
        for ci in range(len(col_bounds) - 1):
            c0, c1 = col_bounds[ci] + 1, col_bounds[ci + 1]
            blocks.append((r0, r1, c0, c1))

    source = max(
        blocks,
        key=lambda b: sum(
            grid[r][c] != bg
            for r in range(b[0], b[1])
            for c in range(b[2], b[3])
        ),
    )
    sr0, sr1, sc0, sc1 = source
    out = [row[:] for row in grid]
    for r0, r1, c0, c1 in blocks:
        if r1 - r0 != sr1 - sr0 or c1 - c0 != sc1 - sc0:
            continue
        for r in range(r1 - r0):
            for c in range(c1 - c0):
                out[r0 + r][c0 + c] = grid[sr0 + r][sc0 + c]
    return out
